1	<?php
2	declare(strict_types=1);
3	
4	// Single entry for every page and the API. Loads config, libs, session, security headers.
5	define('APP_ROOT', __DIR__ . '/..');
6	define('APP_DIR', __DIR__);
7	
8	$GLOBALS['APP_CONFIG'] = null;
9	$cfgFile = APP_DIR . '/config.local.php';
10	if (is_file($cfgFile)) {
11	    $GLOBALS['APP_CONFIG'] = require $cfgFile;
12	}
13	
14	function config(string $key, $default = null)
15	{
16	    $c = $GLOBALS['APP_CONFIG'] ?? [];
17	    return $c[$key] ?? $default;
18	}
19	
20	function app_installed(): bool
21	{
22	    return $GLOBALS['APP_CONFIG'] !== null && is_file(APP_ROOT . '/storage/installed.lock');
23	}
24	
25	require_once APP_DIR . '/lib/http.php';
26	require_once APP_DIR . '/lib/db.php';
27	require_once APP_DIR . '/lib/csrf.php';
28	require_once APP_DIR . '/lib/validate.php';
29	require_once APP_DIR . '/lib/audit.php';
30	require_once APP_DIR . '/lib/auth.php';
31	require_once APP_DIR . '/lib/i18n.php';
32	require_once APP_DIR . '/lib/repo/establishments.php';
33	
34	if (config('debug', false)) {
35	    ini_set('display_errors', '1');
36	    error_reporting(E_ALL);
37	} else {
38	    ini_set('display_errors', '0');
39	    error_reporting(E_ALL);
40	    ini_set('log_errors', '1');
41	}
42	
43	date_default_timezone_set('Asia/Manila');
44	
45	if (session_status() === PHP_SESSION_NONE) {
46	    $https = (!empty($_SERVER['HTTPS']) && $_SERVER['HTTPS'] !== 'off')
47	          || (($_SERVER['HTTP_X_FORWARDED_PROTO'] ?? '') === 'https');
48	    session_name('BRGYSESS');
49	    session_set_cookie_params([
50	        'lifetime' => 0,
51	        'path'     => '/',
52	        'secure'   => $https,
53	        'httponly' => true,
54	        'samesite' => 'Lax',
55	    ]);
56	    session_start();
57	}
58	
59	// Security headers. CSP allows only self + the pinned Leaflet CDN (if used) + the configured tile host (img-src https:).
60	if (!headers_sent()) {
61	    header('X-Content-Type-Options: nosniff');
62	    header('X-Frame-Options: SAMEORIGIN');
63	    // Tile servers (incl. OSM) require a Referer; send only the origin, never the full path, to other sites.
64	    header('Referrer-Policy: strict-origin-when-cross-origin');
65	    header('Permissions-Policy: geolocation=(self), camera=(), microphone=()');
66	    header("Content-Security-Policy: default-src 'self'; img-src 'self' data: https:; "
67	         . "style-src 'self' 'unsafe-inline' https://unpkg.com;script-src 'self' https://unpkg.com; connect-src 'self' https:; "
68	         . "frame-ancestors 'self'; base-uri 'self'; form-action 'self'");
69	}
