4	function h($v): string
5	{
6	    return htmlspecialchars((string)$v, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8');
7	}
8	
9	function base_url(): string
10	{
11	    return rtrim((string)config('base_url', ''), '/');
12	}
13	
14	function url(string $path = ''): string
15	{
16	    return base_url() . '/' . ltrim($path, '/');
17	}
18	
19	function redirect(string $path): void
20	{
21	    header('Location: ' . (preg_match('#^https?://#', $path) ? $path : url($path)));
22	    exit;
23	}
24	
25	function client_ip(): string
26	{
27	    // REMOTE_ADDR only: forwarded headers are client-controlled and not trusted here.
28	    return (string)($_SERVER['REMOTE_ADDR'] ?? '0.0.0.0');
29	}
30	
31	function ip_hash(): string
32	{
33	    return hash('sha256', client_ip() . '|' . (string)config('app_salt', ''));
34	}
35	
36	function json_out($data, int $status = 200): void
37	{
38	    http_response_code($status);
39	    header('Content-Type: application/json; charset=utf-8');
40	    header('Cache-Control: no-store');
41	    echo json_encode($data, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES | JSON_INVALID_UTF8_SUBSTITUTE);
42	    exit;
43	}
44	
45	function json_error(string $message, int $status = 400, array $extra = []): void
46	{
47	    json_out(['ok' => false, 'error' => $message] + $extra, $status);
48	}
49	
50	function request_json(): array
51	{
52	    $raw = file_get_contents('php://input', false, null, 0, 65536);
53	    if ($raw === false || $raw === '') {
54	        return [];
55	    }
56	    $d = json_decode($raw, true);
57	    return is_array($d) ? $d : [];
58	}
