23	/** Read one app_settings value (cached per request). */
24	function setting(string $key, ?string $default = null): ?string
25	{
26	    static $cache = null;
27	    if ($cache === null) {
28	        $cache = [];
29	        try {
30	            foreach (db()->query('SELECT setting_key, setting_value FROM app_settings') as $r) {
31	                $cache[$r['setting_key']] = $r['setting_value'];
32	            }
33	        } catch (Throwable $e) {
34	            $cache = [];
35	        }
36	    }
37	    return array_key_exists($key, $cache) && $cache[$key] !== null ? $cache[$key] : $default;
38	}
