40	function set_setting(string $key, string $value): void
41	{
42	    $st = db()->prepare('INSERT INTO app_settings (setting_key, setting_value) VALUES (?, ?)
43	                         ON DUPLICATE KEY UPDATE setting_value = VALUES(setting_value)');
44	    $st->execute([$key, $value]);
45	}
