4	const MAX_FAILED_LOGINS = 5;
5	const LOCK_MINUTES      = 15;
6	
7	/** Permissions are code constants: role_key => list of permission keys. */
8	const ROLE_PERMISSIONS = [
9	    'admin' => ['*'],
10	    'verifier' => [
11	        'establishments.view', 'establishments.edit', 'establishments.verify',
12	        'requests.review', 'audit.view', 'export.run',
13	    ],
