19	function currentUser(): ?array
20	{
21	    return $_SESSION['user'] ?? null;
22	}
23	
24	function can(string $permission): bool
25	{
26	    $u = currentUser();
27	    if (!$u) {
28	        return false;
29	    }
30	    $perms = ROLE_PERMISSIONS[$u['role_key']] ?? [];
31	    return in_array('*', $perms, true) || in_array($permission, $perms, true);
32	}
