64	/**
65	 * Attempt login. Returns [bool ok, string message]. Same message for unknown user / wrong password.
66	 */
67	function attemptLogin(string $username, string $password): array
68	{
69	    $generic = 'Incorrect username or password.';
70	    $st = db()->prepare('SELECT u.*, r.role_key FROM users u JOIN roles r ON r.role_id = u.role_id WHERE u.username = ?');
71	    $st->execute([$username]);
72	    $u = $st->fetch();
73	
74	    if (!$u) {
75	        // Burn comparable time so unknown usernames are not distinguishable by speed.
76	        password_verify($password, password_hash('dummy-not-a-real-password', PASSWORD_DEFAULT));
77	        return [false, $generic];
78	    }
79	    if ($u['status'] !== 'active') {
80	        return [false, 'This account is disabled. Contact the administrator.'];
81	    }
82	    if ($u['locked_until'] !== null && strtotime((string)$u['locked_until']) > time()) {
83	        return [false, 'Too many failed attempts. Try again in a few minutes.'];
84	    }
85	    if (!password_verify($password, $u['password_hash'])) {
86	        $fails = (int)$u['failed_logins'] + 1;
87	        if ($fails >= MAX_FAILED_LOGINS) {
88	            db()->prepare('UPDATE users SET failed_logins = 0, locked_until = DATE_ADD(NOW(), INTERVAL ' . LOCK_MINUTES . ' MINUTE) WHERE user_id = ?')
89	                ->execute([$u['user_id']]);
90	        } else {
91	            db()->prepare('UPDATE users SET failed_logins = ? WHERE user_id = ?')->execute([$fails, $u['user_id']]);
92	        }
93	        logAudit('login_failed', 'user', (int)$u['user_id'], 'username=' . $username);
94	        return [false, $generic];
95	    }
96	
97	    if (password_needs_rehash($u['password_hash'], PASSWORD_DEFAULT)) {
98	        db()->prepare('UPDATE users SET password_hash = ? WHERE user_id = ?')
99	            ->execute([password_hash($password, PASSWORD_DEFAULT), $u['user_id']]);
100	    }
101	    db()->prepare('UPDATE users SET failed_logins = 0, locked_until = NULL, last_login_at = NOW() WHERE user_id = ?')
102	        ->execute([$u['user_id']]);
103	
104	    session_regenerate_id(true);
105	    $_SESSION['csrf'] = bin2hex(random_bytes(32));
106	    $_SESSION['user'] = [
107	        'user_id'     => (int)$u['user_id'],
108	        'username'    => $u['username'],
109	        'full_name'   => $u['full_name'],
110	        'role_key'    => $u['role_key'],
111	        'barangay_id' => $u['barangay_id'] !== null ? (int)$u['barangay_id'] : null,
112	    ];
113	    logAudit('login', 'user', (int)$u['user_id']);
114	    return [true, 'ok'];
115	}
116	
117	function logout(): void
118	{
119	    logAudit('logout', 'user', currentUser()['user_id'] ?? null);
120	    $_SESSION = [];
121	    if (ini_get('session.use_cookies')) {
122	        $p = session_get_cookie_params();
123	        setcookie(session_name(), '', time() - 42000, $p['path'], $p['domain'] ?? '', $p['secure'], $p['httponly']);
124	    }
125	    session_destroy();
126	}
