128	/** Password policy for admin-created accounts. Returns error string or null. */
129	function password_policy_error(string $pw): ?string
130	{
131	    if (strlen($pw) < 10) {
132	        return 'Password must be at least 10 characters.';
133	    }
134	    if (!preg_match('/[A-Za-z]/', $pw) || !preg_match('/\d/', $pw)) {
135	        return 'Password must contain letters and numbers.';
136	    }
137	    return null;
138	}
