1	<?php
2	declare(strict_types=1);
3	
4	// JSON API front controller. api/.htaccess rewrites /api/foo/bar -> index.php?r=foo/bar
5	// (calling index.php?r=foo/bar directly also works if mod_rewrite is unavailable).
6	require __DIR__ . '/../app/bootstrap.php';
7	
8	if (!app_installed()) {
9	    json_error('System is not installed.', 503);
10	}
11	
12	$route  = trim((string)($_GET['r'] ?? ''), '/');
13	$method = $_SERVER['REQUEST_METHOD'] ?? 'GET';
14	$parts  = $route === '' ? [] : explode('/', $route);
15	
16	/** Collect and sanitise common filters from the query string. */
17	function api_filters(): array
18	{
19	    $f = [];
20	    foreach (['barangay_id', 'category_id'] as $k) {
21	        if (isset($_GET[$k]) && ctype_digit((string)$_GET[$k])) {
22	            $f[$k] = (int)$_GET[$k];
23	        }
24	    }
25	    if (isset($_GET['q'])) {
26	        $q = clean_str($_GET['q'], 100);
27	        if ($q !== null) {
28	            $f['q'] = $q;
29	        }
30	    }
31	    if (isset($_GET['zone'])) {
32	        $z = clean_str($_GET['zone'], 80);
33	        if ($z !== null) {
34	            $f['zone'] = $z;
35	        }
36	    }
37	    if (isset($_GET['classification']) && in_array($_GET['classification'], ['public', 'private'], true)) {
38	        $f['classification'] = $_GET['classification'];
39	    }
40	    foreach (['essential', 'emergency'] as $k) {
41	        if (!empty($_GET[$k]) && $_GET[$k] !== '0') {
42	            $f[$k] = true;
43	        }
44	    }
45	    return $f;
46	}
47	
48	function api_int(string $k, int $def, int $min, int $max): int
49	{
50	    if (!isset($_GET[$k]) || !preg_match('/^-?\d+$/', (string)$_GET[$k])) {
51	        return $def;
52	    }
53	    return max($min, min($max, (int)$_GET[$k]));
54	}
55	
56	try {
57	    if ($method === 'GET') {
58	        switch (true) {
59	            case $parts === ['establishments']:
60	                $res = repo_search(api_filters(), api_int('limit', 50, 1, 200), api_int('offset', 0, 0, 100000));
61	                json_out(['ok' => true, 'total' => $res['total'], 'items' => $res['items']]);
62	
63	            case $parts === ['establishments', 'nearby']:
64	                $lat = parse_lat($_GET['lat'] ?? null);
65	                $lng = parse_lng($_GET['lng'] ?? null);
66	                if ($lat === null || $lng === null) {
67	                    json_error('lat and lng are required and must be valid coordinates.', 422);
68	                }
69	                $items = repo_nearby($lat, $lng, api_int('radius', 1000, 50, 20000), api_filters(), api_int('limit', 30, 1, 100));
70	                json_out(['ok' => true, 'distance_kind' => 'straight_line', 'items' => $items]);
71	
72	            case count($parts) === 2 && $parts[0] === 'establishments' && ctype_digit($parts[1]):
73	                $e = repo_find((int)$parts[1]);
74	                if (!$e) {
75	                    json_error('Establishment not found.', 404);
76	                }
77	                json_out(['ok' => true, 'item' => $e]);
78	
79	            case $parts === ['categories']:
80	                json_out(['ok' => true, 'items' => repo_categories()]);
81	
82	            case $parts === ['barangays']:
83	                json_out(['ok' => true, 'items' => repo_barangays()]);
84	
85	            case $parts === ['zones']:
86	                json_out(['ok' => true, 'items' => repo_zones(isset($_GET['barangay_id']) && ctype_digit((string)$_GET['barangay_id']) ? (int)$_GET['barangay_id'] : null)]);
87	
88	            case $parts === ['facilities']:
89	                json_out(['ok' => true, 'items' => repo_facilities(api_filters())]);
90	
91	            case $parts === ['map', 'markers']:
92	                json_out(['ok' => true, 'items' => repo_markers(api_filters())]);
93	
94	            case $parts === ['config']:
95	                // Public client config: map tiles + routing mode. No secrets here.
96	                json_out(['ok' => true,
97	                    'site_title'  => setting('site_title', 'Barangay Establishment Locator'),
98	                    'tile_url'    => setting('tile_url'),
99	                    'tile_attribution' => setting('tile_attribution'),
100	                    'tile_is_production_ok' => setting('tile_is_production_ok', '0') === '1',
101	                    'routing_provider' => setting('routing_provider', 'external_link'),
102	                    'external_nav_url' => setting('external_nav_url'),
103	                    'kiosk_idle_seconds' => (int)setting('kiosk_idle_seconds', '90'),
104	                    'show_sample_banner' => setting('show_sample_banner', '1') === '1',
105	                ]);
106	
107	            default:
108	                json_error('Unknown endpoint.', 404);
109	        }
110	    }
111	
112	    if ($method === 'POST' && $parts === ['reports']) {
113	        handle_report();
114	    }
115	
116	    json_error('Method not allowed.', 405);
117	} catch (Throwable $e) {
118	    error_log('API error: ' . $e->getMessage());
119	    json_error(config('debug', false) ? $e->getMessage() : 'Server error.', 500);
120	}
121	
122	/**
123	 * Public report/suggestion. NEVER publishes anything: it only creates a pending change request
124	 * for staff to review. Protected by CSRF, a honeypot, per-IP daily limit and a payload size cap.
125	 */
126	function handle_report(): void
127	{
128	    $in = request_json();
129	    if (!$in) {
130	        $in = $_POST;
131	    }
132	    $tok = $_SERVER['HTTP_X_CSRF_TOKEN'] ?? ($in['csrf'] ?? null);
133	    if (!csrf_valid(is_string($tok) ? $tok : null)) {
134	        json_error('Session expired. Refresh the page and try again.', 403);
135	    }
136	    if (!empty($in['website'] ?? '')) { // honeypot: humans leave this empty
137	        json_out(['ok' => true, 'message' => 'Thank you.']);
138	    }
139	
140	    $limit = max(1, (int)setting('reports_per_ip_per_day', '5'));
141	    $st = db()->prepare('SELECT COUNT(*) FROM establishment_change_requests WHERE ip_hash = ? AND created_at > DATE_SUB(NOW(), INTERVAL 1 DAY)');
142	    $st->execute([ip_hash()]);
143	    if ((int)$st->fetchColumn() >= $limit) {
144	        json_error('Too many submissions today. Please try again tomorrow.', 429);
145	    }
146	
147	    $type = (string)($in['request_type'] ?? '');
148	    if (!in_array($type, ['new', 'correction', 'report_incorrect'], true)) {
149	        json_error('Invalid request type.', 422);
150	    }
151	    $estId = null;
152	    if ($type !== 'new') {
153	        if (!isset($in['establishment_id']) || !ctype_digit((string)$in['establishment_id'])) {
154	            json_error('establishment_id is required.', 422);
155	        }
156	        $estId = (int)$in['establishment_id'];
157	        $q = db()->prepare('SELECT barangay_id FROM establishments WHERE establishment_id = ?');
158	        $q->execute([$estId]);
159	        $barangayId = $q->fetchColumn();
160	        if ($barangayId === false) {
161	            json_error('Establishment not found.', 404);
162	        }
163	        $barangayId = (int)$barangayId;
164	    } else {
165	        if (!isset($in['barangay_id']) || !ctype_digit((string)$in['barangay_id'])) {
166	            json_error('barangay_id is required.', 422);
167	        }
168	        $barangayId = (int)$in['barangay_id'];
169	        $q = db()->prepare('SELECT 1 FROM barangays WHERE barangay_id = ? AND is_active = 1');
170	        $q->execute([$barangayId]);
171	        if (!$q->fetchColumn()) {
172	            json_error('Barangay not found.', 404);
173	        }
174	    }
175	
176	    $payload = [
177	        'name'        => clean_str($in['name'] ?? null, 160),
178	        'category_id' => isset($in['category_id']) && ctype_digit((string)$in['category_id']) ? (int)$in['category_id'] : null,
179	        'address'     => clean_str($in['address'] ?? null, 255),
180	        'landmark'    => clean_str($in['landmark'] ?? null, 255),
181	        'zone'        => clean_str($in['zone'] ?? null, 80),
182	        'phone'       => clean_str($in['phone'] ?? null, 60),
183	        'message'     => clean_str($in['message'] ?? null, 1000),
184	    ];
185	    if ($type === 'new' && $payload['name'] === null) {
186	        json_error('Please enter the establishment name.', 422);
187	    }
188	    if ($type !== 'new' && $payload['message'] === null && $payload['name'] === null && $payload['address'] === null) {
189	        json_error('Please describe what is wrong or what should change.', 422);
190	    }
191	    [$lat, $lng, $coordErr] = validate_coords($in['lat'] ?? null, $in['lng'] ?? null);
192	    if ($coordErr) {
193	        json_error($coordErr, 422);
194	    }
195	    // Submitted coordinates are stored in the request for staff to check; they are never trusted as verified.
196	    $payload['lat'] = $lat;
197	    $payload['lng'] = $lng;
198	
199	    $json = json_encode($payload, JSON_UNESCAPED_UNICODE);
200	    if ($json === false || strlen($json) > 8000) {
201	        json_error('Submission is too large.', 413);
202	    }
203	
204	    $contact = clean_str($in['submitter_contact'] ?? null, 190);
205	    $ins = db()->prepare('INSERT INTO establishment_change_requests
206	        (establishment_id, barangay_id, request_type, payload, submitter_name, submitter_contact, ip_hash)
207	        VALUES (?, ?, ?, ?, ?, ?, ?)');
208	    $ins->execute([$estId, $barangayId, $type, $json, clean_str($in['submitter_name'] ?? null, 120), $contact, ip_hash()]);
209	
210	    json_out(['ok' => true, 'message' => 'Thank you. Your submission will be reviewed by barangay staff before anything is published.'], 201);
211	}
