89	/** Shape a DB row into the public JSON structure, enforcing the visibility rules. */
90	function repo_shape(array $r): array
91	{
92	    $hasCoords = $r['latitude'] !== null && $r['longitude'] !== null;
93	    $plottable = $hasCoords && ((int)$r['coords_verified'] === 1 || !repo_plot_requires_verified());
94	    $emergency = (int)($r['f_is_emergency'] ?? 0) === 1 && !empty($r['f_emergency_verified_at']);
95	
96	    return [
97	        'id'              => (int)$r['establishment_id'],
98	        'name'            => $r['name'],
99	        'description'     => $r['description'],
100	        'barangay_id'     => (int)$r['barangay_id'],
101	        'barangay'        => $r['barangay_name'],
102	        'category'        => [
103	            'id'    => (int)$r['primary_category_id'],
104	            'slug'  => $r['category_slug'],
105	            'name'  => cat_name(['name_en' => $r['category_name_en'], 'name_tl' => $r['category_name_tl']]),
106	            'icon'  => $r['category_icon'],
107	            'color' => $r['category_color'],
108	            'essential' => (int)$r['category_is_essential'] === 1,
109	        ],
110	        'address'         => $r['street_address'],
111	        'landmark'        => $r['landmark'],
112	        'directions'      => $r['directions_text'],
113	        'zone'            => $r['zone'],
114	        'classification'  => $r['classification'],
115	        'status'          => $r['status'],
116	        'verified'        => $r['status'] === 'verified',
117	        'last_verified_at'=> $r['last_verified_at'],
118	        'hours_note'      => $r['hours_note'],
119	        'photo_url'       => $r['photo_path'] ? url('uploads/' . rawurlencode(basename((string)$r['photo_path']))) : null,
120	        'is_sample'       => (int)$r['is_sample'] === 1,
121	        'osm_sourced'     => !empty($r['osm_ref']),
122	        'has_coordinates' => $hasCoords,
123	        'plottable'       => $plottable,
124	        'coords_verified' => (int)$r['coords_verified'] === 1,
125	        // Coordinates are only sent when the point may be plotted; otherwise the record is list-only.
126	        'lat'             => $plottable ? (float)$r['latitude'] : null,
127	        'lng'             => $plottable ? (float)$r['longitude'] : null,
128	        'emergency'       => $emergency,
129	        'facility_type'   => $r['f_type'] ?? null,
130	        'services'        => $r['f_services'] ?? null,
131	    ];
