205	/**
206	 * Nearby, ranked by STRAIGHT-LINE (great-circle) distance in metres. This is NOT walking or driving distance
207	 * and the API labels it so.
208	 */
209	function repo_nearby(float $lat, float $lng, int $radiusM = 1000, array $f = [], int $limit = 30): array
210	{
211	    $radiusM = max(50, min(20000, $radiusM));
212	    $limit = max(1, min(100, $limit));
213	
214	    $dLat = $radiusM / 111320.0;
215	    $dLng = $radiusM / (111320.0 * max(0.01, cos(deg2rad($lat))));
216	
217	    $params = [];
218	    $where = repo_build_where($f, $params)
219	        . ' AND e.latitude IS NOT NULL AND e.longitude IS NOT NULL AND e.latitude BETWEEN ? AND ? AND e.longitude BETWEEN ? AND ?';
220	    if (repo_plot_requires_verified()) {
221	        $where .= ' AND e.coords_verified = 1';
222	    }
223	    array_push($params, $lat - $dLat, $lat + $dLat, $lng - $dLng, $lng + $dLng);
224	
225	    $dist = '(6371000 * 2 * ASIN(SQRT(POW(SIN(RADIANS(e.latitude - ?) / 2), 2) + COS(RADIANS(?)) * COS(RADIANS(e.latitude)) * POW(SIN(RADIANS(e.longitude - ?) / 2), 2))))';
226	    $sql = "SELECT " . REPO_SELECT . ", $dist AS straight_line_m " . REPO_FROM . " WHERE $where HAVING straight_line_m <= ? ORDER BY straight_line_m ASC LIMIT $limit";
227	    $all = array_merge([$lat, $lat, $lng], $params, [$radiusM]);
228	    $st = db()->prepare($sql);
229	    $st->execute($all);
230	
231	    $out = [];
232	    foreach ($st->fetchAll() as $r) {
233	        $s = repo_shape($r);
234	        $s['straight_line_m'] = (int)round((float)$r['straight_line_m']);
235	        $s['distance_note'] = 'straight_line_not_route';
236	        $out[] = $s;
237	    }
238	    return $out;
239	}
