104	      if (userMarker) { map.removeLayer(userMarker); }
105	      userMarker = L.circleMarker(userPos, { radius: 9, color: '#fff', weight: 3, fillColor: '#2563eb', fillOpacity: 1 }).addTo(map).bindTooltip('You');
