115	    if (!cfg.tile_is_production_ok && /tile\.openstreetmap\.org/.test(cfg.tile_url || '')) {
116	      var w = document.getElementById('tile-warn'); if (w) { w.hidden = false; }
117	    }
118	    var b = res[1].items[0];
119	    if (b && b.center) { map.setView(b.center, b.zoom || 16); }
120	    // Draw a boundary only when the barangay supplied one together with its source.
121	    res[1].items.forEach(function (br) {
122	      if (br.boundary && br.boundary_source) {
