17	/** Validate and store an uploaded photo. Returns [filename|null, error|null]. */
18	function handle_photo_upload(): array
19	{
20	    if (empty($_FILES['photo']) || ($_FILES['photo']['error'] ?? UPLOAD_ERR_NO_FILE) === UPLOAD_ERR_NO_FILE) {
21	        return [null, null];
22	    }
23	    $f = $_FILES['photo'];
24	    if ($f['error'] !== UPLOAD_ERR_OK) { return [null, 'Photo upload failed.']; }
25	    if ($f['size'] > 2 * 1024 * 1024) { return [null, 'Photo must be 2 MB or smaller.']; }
26	    if (!is_uploaded_file($f['tmp_name'])) { return [null, 'Invalid upload.']; }
27	    $fi = new finfo(FILEINFO_MIME_TYPE);
28	    $mime = $fi->file($f['tmp_name']);
29	    $ext = ['image/jpeg' => 'jpg', 'image/png' => 'png', 'image/webp' => 'webp'][$mime] ?? null;
30	    if ($ext === null || @getimagesize($f['tmp_name']) === false) { return [null, 'Photo must be a JPG, PNG or WebP image.']; }
31	    $name = bin2hex(random_bytes(16)) . '.' . $ext;
32	    if (!move_uploaded_file($f['tmp_name'], APP_ROOT . '/uploads/' . $name)) { return [null, 'Could not store the photo.']; }
33	    return [$name, null];
34	}
