19	/** Possible duplicates: same normalised name in the barangay, or another record within ~25 m. */
20	function est_find_duplicates(int $barangayId, string $name, ?float $lat, ?float $lng, ?int $excludeId): array
21	{
22	    $norm = est_norm_name($name);
23	    $st = db()->prepare('SELECT establishment_id, name, street_address, latitude, longitude, status FROM establishments
24	                         WHERE barangay_id = ? AND establishment_id <> ? AND status <> "inactive"');
25	    $st->execute([$barangayId, $excludeId ?? 0]);
26	    $out = [];
27	    foreach ($st->fetchAll() as $r) {
28	        $sameName = $norm !== '' && est_norm_name($r['name']) === $norm;
29	        $close = false;
30	        if ($lat !== null && $lng !== null && $r['latitude'] !== null) {
31	            $dy = ($lat - (float)$r['latitude']) * 111320.0;
32	            $dx = ($lng - (float)$r['longitude']) * 111320.0 * cos(deg2rad($lat));
33	            $close = sqrt($dx * $dx + $dy * $dy) <= 25.0;
34	        }
35	        if ($sameName || $close) {
36	            $r['reason'] = $sameName ? 'same name' : 'within 25 m';
37	            $out[] = $r;
38	        }
39	    }
40	    return $out;
41	}
