46	function est_validate(array $in): array
47	{
48	    $err = [];
49	    $d = [];
50	    $d['name'] = clean_str($in['name'] ?? null, 160);
51	    if ($d['name'] === null) { $err[] = 'Name is required.'; }
52	
53	    $d['barangay_id'] = isset($in['barangay_id']) && ctype_digit((string)$in['barangay_id']) ? (int)$in['barangay_id'] : 0;
54	    if (!$d['barangay_id']) { $err[] = 'Barangay is required.'; }
55	    elseif (!canAccessBarangay($d['barangay_id'])) { $err[] = 'You cannot manage that barangay.'; }
56	
57	    $d['primary_category_id'] = isset($in['primary_category_id']) && ctype_digit((string)$in['primary_category_id']) ? (int)$in['primary_category_id'] : 0;
58	    if (!$d['primary_category_id']) { $err[] = 'Category is required.'; }
59	
60	    $d['description']    = clean_str($in['description'] ?? null, 2000);
61	    $d['street_address'] = clean_str($in['street_address'] ?? null, 255);
62	    $d['landmark']       = clean_str($in['landmark'] ?? null, 255);
63	    $d['directions_text'] = clean_str($in['directions_text'] ?? null, 1500);
64	    $d['zone']         = clean_str($in['zone'] ?? null, 80);
65	    $d['hours_note']     = clean_str($in['hours_note'] ?? null, 255);
66	    $d['data_source']    = clean_str($in['data_source'] ?? null, 255);
67	    $d['coords_source']  = clean_str($in['coords_source'] ?? null, 255);
68	    $d['classification'] = ($in['classification'] ?? '') === 'public' ? 'public' : 'private';
69	
70	    [$lat, $lng, $ce] = validate_coords($in['latitude'] ?? null, $in['longitude'] ?? null);
71	    if ($ce) { $err[] = $ce; }
72	    $d['latitude'] = $lat;
73	    $d['longitude'] = $lng;
74	
75	    // Contacts (public).
76	    $d['contacts'] = [];
77	    $phone = clean_str($in['phone'] ?? null, 60);
78	    if ($phone !== null) { $d['contacts'][] = ['phone', $phone]; }
79	    $mobile = clean_str($in['mobile'] ?? null, 60);
80	    if ($mobile !== null) { $d['contacts'][] = ['mobile', $mobile]; }
81	    $email = clean_str($in['email'] ?? null, 190);
82	    if ($email !== null) {
83	        if (!valid_email($email)) { $err[] = 'Email address is not valid.'; } else { $d['contacts'][] = ['email', $email]; }
84	    }
85	    $web = clean_str($in['website'] ?? null, 190);
86	    if ($web !== null) {
87	        if (!valid_http_url($web)) { $err[] = 'Website must start with http:// or https://'; } else { $d['contacts'][] = ['website', $web]; }
88	    }
89	
90	    // Weekly hours: day => [open, close, closed, 24h]
91	    $d['hours'] = [];
92	    for ($i = 0; $i < 7; $i++) {
93	        $closed = !empty($in["h{$i}_closed"]);
94	        $h24    = !empty($in["h{$i}_24h"]);
95	        $o = trim((string)($in["h{$i}_open"] ?? ''));
96	        $c = trim((string)($in["h{$i}_close"] ?? ''));
97	        if ($closed) { $d['hours'][$i] = [null, null, 1, 0]; continue; }
98	        if ($h24)    { $d['hours'][$i] = [null, null, 0, 1]; continue; }
99	        if ($o === '' && $c === '') { continue; }
100	        if (!preg_match('/^([01]\d|2[0-3]):[0-5]\d$/', $o) || !preg_match('/^([01]\d|2[0-3]):[0-5]\d$/', $c)) {
101	            $err[] = "Hours for day $i must be HH:MM."; continue;
102	        }
103	        $d['hours'][$i] = [$o . ':00', $c . ':00', 0, 0];
104	    }
105	
106	    // Facility flags.
107	    $d['facility_type'] = in_array($in['facility_type'] ?? '', ['government','health','safety','education','evacuation','transport','utility','other'], true)
108	        ? $in['facility_type'] : null;
109	    $d['is_emergency']  = !empty($in['is_emergency']) ? 1 : 0;
110	    $d['services_offered'] = clean_str($in['services_offered'] ?? null, 2000);
111	    return [$d, $err];
