114	/** Persist. Returns the establishment id. Throws on DB errors. */
115	function est_save(array $d, ?int $id, array $user, bool $canVerify): int
116	{
117	    $pdo = db();
118	    $pdo->beginTransaction();
119	    try {
120	        if ($id === null) {
121	            $st = $pdo->prepare('INSERT INTO establishments (barangay_id, name, description, primary_category_id, street_address, landmark, directions_text, zone,
122	                latitude, longitude, coords_verified, coords_source, classification, status, data_source, hours_note, created_by)
123	                VALUES (?,?,?,?,?,?,?,?,?,?,0,?,?,"pending_verification",?,?,?)');
124	            $st->execute([$d['barangay_id'], $d['name'], $d['description'], $d['primary_category_id'], $d['street_address'], $d['landmark'], $d['directions_text'], $d['zone'],
125	                $d['latitude'], $d['longitude'], $d['coords_source'], $d['classification'], $d['data_source'], $d['hours_note'], $user['user_id']]);
126	            $id = (int)$pdo->lastInsertId();
127	            $pdo->prepare('INSERT INTO verification_records (establishment_id, action, to_status, user_id) VALUES (?, "created", "pending_verification", ?)')
128	                ->execute([$id, $user['user_id']]);
129	        } else {
130	            $old = est_get($id);
131	            if (!$old) { throw new RuntimeException('Record not found'); }
132	            // Coordinates changed => they must be re-checked.
133	            $moved = ((string)$old['latitude'] !== (string)($d['latitude'] === null ? '' : number_format($d['latitude'], 7, '.', '')))
134	                  || ((string)$old['longitude'] !== (string)($d['longitude'] === null ? '' : number_format($d['longitude'], 7, '.', '')));
135	            $coordsVerified = ($moved || $d['latitude'] === null) ? 0 : (int)$old['coords_verified'];
136	            // A non-verifier editing a verified record sends it back for verification.
137	            $status = $old['status'];
138	            if ($status === 'verified' && !$canVerify) { $status = 'pending_verification'; }
139	
140	            $st = $pdo->prepare('UPDATE establishments SET barangay_id=?, name=?, description=?, primary_category_id=?, street_address=?, landmark=?, directions_text=?, zone=?,
141	                latitude=?, longitude=?, coords_verified=?, coords_source=?, classification=?, status=?, data_source=?, hours_note=? WHERE establishment_id=?');
142	            $st->execute([$d['barangay_id'], $d['name'], $d['description'], $d['primary_category_id'], $d['street_address'], $d['landmark'], $d['directions_text'], $d['zone'],
143	                $d['latitude'], $d['longitude'], $coordsVerified, $d['coords_source'], $d['classification'], $status, $d['data_source'], $d['hours_note'], $id]);
144	            $pdo->prepare('INSERT INTO verification_records (establishment_id, action, from_status, to_status, note, user_id) VALUES (?, "edited", ?, ?, ?, ?)')
145	                ->execute([$id, $old['status'], $status, $moved ? 'coordinates changed; re-check required' : null, $user['user_id']]);
146	        }
147	
148	        // Replace contacts and hours (simple, small child sets).
149	        $pdo->prepare('DELETE FROM establishment_contacts WHERE establishment_id = ?')->execute([$id]);
150	        $ci = $pdo->prepare('INSERT INTO establishment_contacts (establishment_id, contact_type, contact_value) VALUES (?,?,?)');
151	        foreach ($d['contacts'] as [$t, $v]) { $ci->execute([$id, $t, $v]); }
152	
153	        $pdo->prepare('DELETE FROM operating_hours WHERE establishment_id = ?')->execute([$id]);
154	        $hi = $pdo->prepare('INSERT INTO operating_hours (establishment_id, day_of_week, opens_at, closes_at, is_closed, is_24h) VALUES (?,?,?,?,?,?)');
155	        foreach ($d['hours'] as $dow => [$o, $c, $closed, $h24]) { $hi->execute([$id, $dow, $o, $c, $closed, $h24]); }
156	
157	        // Facility row: keep existing emergency verification unless the emergency flag was turned off.
158	        $ex = $pdo->prepare('SELECT is_emergency, emergency_verified_at FROM facilities WHERE establishment_id = ?');
159	        $ex->execute([$id]);
160	        $f = $ex->fetch();
161	        if ($d['facility_type'] !== null || $d['is_emergency'] || $d['services_offered'] !== null || $f) {
162	            $verifiedAt = ($f && $d['is_emergency'] && $f['emergency_verified_at']) ? $f['emergency_verified_at'] : null;
163	            $pdo->prepare('INSERT INTO facilities (establishment_id, facility_type, is_emergency, emergency_verified_at, services_offered)
164	                           VALUES (?,?,?,?,?) ON DUPLICATE KEY UPDATE facility_type=VALUES(facility_type), is_emergency=VALUES(is_emergency),
165	                           emergency_verified_at=VALUES(emergency_verified_at), services_offered=VALUES(services_offered)')
166	                ->execute([$id, $d['facility_type'] ?? 'other', $d['is_emergency'], $verifiedAt, $d['services_offered']]);
167	        }
168	
169	        // Keep the category link table in sync with the primary category.
170	        $pdo->prepare('DELETE FROM establishment_categories WHERE establishment_id = ?')->execute([$id]);
171	        $pdo->prepare('INSERT INTO establishment_categories (establishment_id, category_id) VALUES (?,?)')->execute([$id, $d['primary_category_id']]);
172	
173	        $pdo->commit();
174	    } catch (Throwable $e) {
175	        if ($pdo->inTransaction()) { $pdo->rollBack(); }
176	        throw $e;
177	    }
178	    return $id;
179	}
