181	/**
182	 * Verification state machine. Returns [ok, message].
183	 * Every transition needs evidence text where it asserts something is true.
184	 */
185	function est_apply_action(int $id, string $action, ?string $evidence, array $user): array
186	{
187	    $e = est_get($id);
188	    if (!$e) { return [false, 'Record not found.']; }
189	    if (!canAccessBarangay((int)$e['barangay_id'])) { return [false, 'You cannot manage that barangay.']; }
190	    $pdo = db();
191	    $from = $e['status'];
192	    $evidence = $evidence !== null ? mb_substr(trim($evidence), 0, 255, 'UTF-8') : null;
193	    if ($evidence === '') { $evidence = null; }
194	
195	    switch ($action) {
196	        case 'verify':
197	            if ($evidence === null) { return [false, 'Describe how this record was verified (e.g. "site visit 2026-10-20 by encoder").']; }
198	            $pdo->prepare('UPDATE establishments SET status="verified", last_verified_at=NOW(), verified_by=? WHERE establishment_id=?')->execute([$user['user_id'], $id]);
199	            $to = 'verified'; $act = 'verify';
200	            break;
201	        case 'flag_review':
202	            $pdo->prepare('UPDATE establishments SET status="needs_review" WHERE establishment_id=?')->execute([$id]);
203	            $to = 'needs_review'; $act = 'flag_review';
204	            break;
205	        case 'deactivate':
206	            $pdo->prepare('UPDATE establishments SET status="inactive" WHERE establishment_id=?')->execute([$id]);
207	            $to = 'inactive'; $act = 'deactivate';
208	            break;
209	        case 'reactivate':
210	            $pdo->prepare('UPDATE establishments SET status="pending_verification" WHERE establishment_id=?')->execute([$id]);
211	            $to = 'pending_verification'; $act = 'reactivate';
212	            break;
213	        case 'coords_verified':
214	            if ($e['latitude'] === null) { return [false, 'This record has no coordinates to verify.']; }
215	            if ($evidence === null) { return [false, 'Describe how the map position was checked.']; }
216	            $pdo->prepare('UPDATE establishments SET coords_verified=1, coords_source=COALESCE(?, coords_source) WHERE establishment_id=?')->execute([$evidence, $id]);
217	            $to = $from; $act = 'coords_verified';
218	            break;
219	        case 'emergency_verified':
220	            $f = $pdo->prepare('SELECT is_emergency FROM facilities WHERE establishment_id=?');
221	            $f->execute([$id]);
222	            if ((int)$f->fetchColumn() !== 1) { return [false, 'This record is not flagged as an emergency facility.']; }
223	            if ($evidence === null) { return [false, 'Describe how the emergency role was confirmed.']; }
224	            $pdo->prepare('UPDATE facilities SET emergency_verified_at=NOW(), emergency_verified_by=? WHERE establishment_id=?')->execute([$user['user_id'], $id]);
225	            $to = $from; $act = 'emergency_verified';
226	            break;
227	        default:
228	            return [false, 'Unknown action.'];
229	    }
230	    $pdo->prepare('INSERT INTO verification_records (establishment_id, action, from_status, to_status, evidence, user_id) VALUES (?,?,?,?,?,?)')
231	        ->execute([$id, $act, $from, $to, $evidence, $user['user_id']]);
232	    logAudit($act, 'establishment', $id, $evidence);
233	    return [true, 'Done.'];
234	}
