18	/** Map OSM tags to one of our category slugs. Returns null when the object is not a useful establishment. */
19	function osm_category(array $t): ?string
20	{
21	    $name    = (string)($t['name'] ?? '');
22	    $amenity = (string)($t['amenity'] ?? '');
23	    $shop    = (string)($t['shop'] ?? '');
24	    $office  = (string)($t['office'] ?? '');
25	    $craft   = (string)($t['craft'] ?? '');
26	
27	    if (preg_match('/(barangay|brgy\.?)\s*(hall|office|outpost)/i', $name)) { return 'barangay-office'; }
28	
29	    $amenityMap = [
30	        'townhall' => 'city-gov-services', 'courthouse' => 'city-gov-services', 'post_office' => 'city-gov-services',
31	        'clinic' => 'health-clinic', 'doctors' => 'health-clinic', 'dentist' => 'health-clinic', 'health_post' => 'health-clinic',
32	        'hospital' => 'hospital-pharmacy', 'pharmacy' => 'hospital-pharmacy',
33	        'school' => 'school', 'kindergarten' => 'school', 'college' => 'school', 'university' => 'school', 'childcare' => 'school', 'library' => 'school',
34	        'police' => 'police', 'fire_station' => 'fire-station', 'place_of_worship' => 'worship',
35	        'restaurant' => 'food', 'fast_food' => 'food', 'cafe' => 'food', 'food_court' => 'food', 'bar' => 'food', 'ice_cream' => 'food', 'canteen' => 'food',
36	        'bank' => 'bank-atm', 'atm' => 'bank-atm',
37	        'money_transfer' => 'remittance', 'bureau_de_change' => 'remittance',
38	        'bus_station' => 'transport', 'taxi' => 'transport', 'ferry_terminal' => 'transport',
39	        'internet_cafe' => 'telecom', 'funeral_hall' => 'funeral', 'marketplace' => 'grocery',
40	        'community_centre' => 'other', 'social_facility' => 'other', 'fuel' => 'other',
41	    ];
42	    if ($amenity !== '' && isset($amenityMap[$amenity])) { return $amenityMap[$amenity]; }
43	
44	    if ($shop !== '') {
45	        if (in_array($shop, ['supermarket', 'convenience', 'greengrocer', 'general', 'butcher', 'seafood', 'bakery', 'variety_store', 'grocery'], true)) { return 'grocery'; }
46	        if (strpos($shop, 'repair') !== false) { return 'repair'; }
47	        if ($shop === 'funeral_directors') { return 'funeral'; }
48	        if ($shop === 'water') { return 'water-refill'; }
49	        if ($shop === 'mobile_phone') { return 'telecom'; }
50	        return 'retail';
51	    }
52	    if ($office !== '') {
53	        if ($office === 'government') { return 'city-gov-services'; }
54	        if ($office === 'telecommunication') { return 'telecom'; }
55	        return 'other';
56	    }
57	    if ($craft !== '') { return strpos($craft, 'repair') !== false ? 'repair' : 'other'; }
58	    if (!empty($t['healthcare'])) { return 'health-clinic'; }
59	    return null;
60	}
