62	/** POST an Overpass QL query. Returns [decoded array|null, error|null]. */
63	function osm_overpass(string $query): array
64	{
65	    $url  = 'https://overpass-api.de/api/interpreter';
66	    $ua   = 'BarangayEstablishmentLocator/1.0 (staff import; ' . ($_SERVER['HTTP_HOST'] ?? 'localhost') . ')';
67	    $body = http_build_query(['data' => $query]);
68	    $raw = false; $code = 0; $err = '';
69	
70	    if (function_exists('curl_init')) {
71	        $ch = curl_init($url);
72	        curl_setopt_array($ch, [
73	            CURLOPT_POST => true, CURLOPT_POSTFIELDS => $body, CURLOPT_RETURNTRANSFER => true,
74	            CURLOPT_TIMEOUT => 40, CURLOPT_CONNECTTIMEOUT => 10, CURLOPT_USERAGENT => $ua,
75	            CURLOPT_HTTPHEADER => ['Accept: application/json'],
76	        ]);
77	        $raw  = curl_exec($ch);
78	        $code = (int)curl_getinfo($ch, CURLINFO_HTTP_CODE);
79	        $err  = curl_error($ch);
80	        curl_close($ch);
81	    } elseif (ini_get('allow_url_fopen')) {
82	        $ctx = stream_context_create(['http' => [
83	            'method' => 'POST', 'timeout' => 40, 'ignore_errors' => true,
84	            'header' => "Content-Type: application/x-www-form-urlencoded\r\nUser-Agent: $ua\r\nAccept: application/json\r\n",
85	            'content' => $body,
86	        ]]);
87	        $raw = @file_get_contents($url, false, $ctx);
88	        if (isset($http_response_header[0]) && preg_match('#\s(\d{3})\s#', $http_response_header[0], $m)) { $code = (int)$m[1]; }
89	    } else {
90	        return [null, 'This server has neither cURL nor allow_url_fopen, so it cannot reach OpenStreetMap. Ask your host to enable cURL.'];
91	    }
92	
93	    if ($raw === false || $raw === '') { return [null, 'Could not reach the OpenStreetMap service' . ($err !== '' ? ' (' . $err . ')' : '') . '. Your host may block outgoing connections.']; }
94	    if ($code === 429 || $code === 504) { return [null, 'The OpenStreetMap service is busy. Wait a minute and try again.']; }
95	    if ($code !== 200) { return [null, 'OpenStreetMap service returned HTTP ' . $code . '.']; }
96	    $j = json_decode((string)$raw, true);
97	    if (!is_array($j) || !isset($j['elements'])) { return [null, 'Unexpected response from OpenStreetMap.']; }
98	    return [$j, null];
99	}
